CREATE TABLE IF NOT EXISTS gis_evidence_verifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), layer_id uuid NOT NULL REFERENCES gis_layers(id) ON DELETE CASCADE, verification_stage text NOT NULL, status text NOT NULL DEFAULT 'Pending', checked_by_reference text, checked_at timestamptz, evidence_reference text, notes text, score numeric(6,2), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS gis_layer_approvals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), layer_id uuid NOT NULL REFERENCES gis_layers(id) ON DELETE CASCADE, decision text NOT NULL DEFAULT 'Pending', decision_reason text, approved_by_reference text, approved_at timestamptz, scope text, expires_at timestamptz, supersedes_id uuid REFERENCES gis_layer_approvals(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_gis_verifications_layer ON gis_evidence_verifications(layer_id,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_gis_approvals_layer ON gis_layer_approvals(layer_id,created_at DESC);